"""Dense filled bestiary silhouettes for tools/genmaps.py (dark body + gold hatch)."""
GOLD = "#c9a45c"
INK = "#0a0e12"

def art(kind, gold=GOLD):
    raw = CREATURE_ART.get(kind) or CREATURE_ART["serpent"]
    if gold == GOLD: return raw
    return raw.replace(GOLD, gold).replace(INK, INK)

